44	    /// Create a new workspace worker.
45	    /// This will not start any programs, use [`start_worker`](Self::start_worker) for that.
46	    /// Depending on the client, we need to request the workspace configuration in `initialized` request.
47	    pub fn new(
48	        root_uri: Uri,
49	        builder: Arc<dyn ToolBuilder>,
50	        diagnostic_mode: DiagnosticMode,
51	    ) -> Self {
52	        Self {
53	            root_uri,
54	            tool: RwLock::new(None),
55	            builder,
56	            options: Mutex::new(None),
57	            diagnostic_mode,
58	            published_diagnostics: Mutex::new(FxHashSet::default()),
59	        }
60	    }
