41	pub fn create_fake_file_path_from_language_id(
42	    language_id: &LanguageId,
43	    root: &Path,
44	    uri: &Uri,
45	) -> Option<PathBuf> {
46	    let file_extension = get_file_extension_from_language_id(language_id)?;
47	    // Use the authority (if available) or the last segment of the path as the file name, defaulting to "Untitled" if neither is available
48	    let mut name = uri.authority().map_or_else(
49	        || uri.path().rsplit_once('/').map_or_else(|| "Untitled", |(_, s)| s.as_str()),
50	        |s| s.as_str(),
51	    );
52	    // if the last character is `/`, the name will be empty, so we need to check for that as well
53	    if name.is_empty() {
54	        name = "Untitled";
55	    }
56	
57	    let file_name = format!("{name}.{file_extension}");
58	    Some(root.join(file_name))
59	}
