/// Run the language server
pub async fn run_server(server_name: String, server_version: String, tool: Arc<dyn ToolBuilder>) {
    let stdin = tokio::io::stdin();
    let stdout = tokio::io::stdout();

    let (service, socket) = LspService::build(|client| {
        // Use a dynamic worker rooted at the filesystem root so files opened
        // outside of any configured workspace folder can still be handled
        // (e.g. formatted). Workspace folders sent during `initialize` still
        // take precedence via the most-specific-worker lookup.
        let dynamic_worker = WorkspaceWorker::new(
            "file:///".parse().expect("`file:///` is a valid URI"),
            Arc::clone(&tool),
            DiagnosticMode::default(),
        );
        let manager = WorkerManager::new_with_mode(
            tool,
            ManagerMode::DynamicWithWorkspaces(Box::new(RwLock::new(dynamic_worker))),
        );
        crate::backend::Backend::new(
            client,
            ServerInfo { name: server_name, version: Some(server_version) },
            manager,
        )
    })
    .finish();

    Server::new(stdin, stdout, socket).serve(service).await;
}
